import fs from "fs";
import { execSync } from "child_process";
let total = 0, problems = [];
for (const sel of ["app-status-pill", "app-fancy-pill"]) {
  const out = execSync(`node .claude/skills/angular-facts/ng-facts.mjs usages ${sel}.disableTooltip --root . --all`).toString();
  for (const m of out.matchAll(/^\s+(\S+?):(\d+)\s+<([a-z-]+)>/gm)) {
    const [, file, lineNo, tag] = m;
    const lines = fs.readFileSync(file, "utf8").split("\n");
    const i = +lineNo - 1, line = lines[i];
    const count = (line.match(/disableTooltip/g) || []).length;
    if (count !== 1 || !line.includes(`<${tag}`)) { problems.push(`${file}:${lineNo}: ${line.trim()}`); continue; }
    lines[i] = line.replace(/\[disableTooltip\]=/, "[hideHint]=").replace(/(\s)disableTooltip(?=[\s>\/=])/, "$1hideHint");
    if (lines[i] === line) { problems.push(`unchanged ${file}:${lineNo}: ${line.trim()}`); continue; }
    fs.writeFileSync(file, lines.join("\n")); total++;
  }
}
console.log("edited", total); for (const p of problems) console.log("!", p);
EOF
