input.command:
cat > /tmp/fix3.mjs <<'EOF'
import fs from "fs";
import { execSync } from "child_process";
let out = "";
try { execSync("npx ngc -p tsconfig.json", { stdio: "pipe" }); } catch (e) { out = e.stdout.toString(); }
const clean = out.replace(/\x1b\[[0-9;]*m/g, "");
const edits = [...clean.matchAll(/^(\S+?):(\d+):(\d+) - error TS2339: Property 'disableTooltip' does not exist on type '(\w+)'/gm)];
const byFile = {};
for (const [, f, l, c, type] of edits) {
  if (!["PillComponent", "FancyPillComponent", "StatusPillComponent"].includes(type)) { console.log("! skip", f, l, type); continue; }
  (byFile[f] ??= []).push([+l, +c]);
}
let n = 0;
for (const [f, locs] of Object.entries(byFile)) {
  const lines = fs.readFileSync(f, "utf8").split("\n");
  for (const [l, c] of locs.sort((a, b) => b[1] - a[1])) {
    const line = lines[l - 1];
    if (line.substr(c - 1, 14) !== "disableTooltip") { console.log("! mismatch", f, l, c); continue; }
    lines[l - 1] = line.slice(0, c - 1) + "hideHint" + line.slice(c - 1 + 14); n++;
  }
  fs.writeFileSync(f, lines.join("\n"));
}
console.log("ts edits", n);
EOF
node /tmp/fix3.mjs

